# Let me try to find cells that are "surrounded" by 1s (local maxima)
def is_surrounded(grid, r, c):
    """Check if this cell is a local maximum (greater than all 8 neighbors)"""
    h, w = len(grid), len(grid[0])
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr, nc] > grid[r, c]:
                    return False
    return True

surrounded = []
for i in range(13):
    for j in range(13):
        if grid[i, j] == 0:
            if is_surrounded(grid, i, j):
                surrounded.append((i, j))

print("Cells that are local maxima (all neighbors have value 0):", len(surrounded))
if surrounded:
    print("Positions:", surrounded)

# Alternative: cells surrounded by 1s (have all 8 neighbors as 1)
def has_1_neighbors(grid, r, c):
    """Count neighbors that are 1"""
    h, w = len(grid), len(grid[0])
    count = 0
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + nc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr, nc] == 1:
                    count += 1
    return count

